// One dated row per AI answer: brand mentioned, position against competitors, site cited, competitors named.
const today = new Date().toISOString().slice(0, 10);
return $input.all()
  .map((i) => i.json)
  .filter((r) => r.found !== false)
  .map((r) => ({
    json: {
      week: today,
      question: r.prompt,
      engine: r.engine,
      brandMentioned: r.brandMentioned,
      brandMentionRank: r.brandMentionRank,
      siteCited: r.brandDomainCited,
      siteCitationRank: r.brandDomainCitationRank,
      competitorsNamed: (r.competitorsMentioned ?? []).join(', '),
      topCitedDomains: (r.citedDomains ?? []).slice(0, 5).join(', '),
      model: r.model,
    },
  }));
